#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){string s;cin>>s;int n=s.size()/2;int digit[10]={0x3f,0x06,0x5b,0x4f,0x66,0x6d,0x7d,0x07,0x7f,0x6f},bits[10],score[10][10];for(int i=0;i<10;i++){bits[i]=__builtin_popcount((unsigned)digit[i]);for(int j=0;j<10;j++)score[i][j]=__builtin_popcount((unsigned)(digit[i]&digit[j]));}int original=0;vector<int>prefix(n+1),maxSuffix(n+1),leftPrefix(n+1);for(int i=0;i<n;i++){prefix[i+1]=prefix[i]+score[s[i]-'0'][s[n+i]-'0'];leftPrefix[i+1]=leftPrefix[i]+bits[s[i]-'0'];}original=prefix[n];for(int i=n-1;i>=0;i--)maxSuffix[i]=maxSuffix[i+1]+bits[s[i]-'0'];int changed=-1;string result=s;for(int i=n-1;i>=0&&changed<0;i--)for(int d=s[n+i]-'0'+1;d<10;d++)if(prefix[i]+score[s[i]-'0'][d]+maxSuffix[i+1]>original){changed=i;result[n+i]='0'+d;break;}if(changed>=0){int sum=prefix[changed]+score[s[changed]-'0'][result[n+changed]-'0'];for(int i=changed+1;i<n;i++)for(int d=0;d<10;d++)if(sum+score[s[i]-'0'][d]+maxSuffix[i+1]>original){result[n+i]='0'+d;sum+=score[s[i]-'0'][d];break;}cout<<result<<'\n';return 0;}for(int i=n-1;i>=0&&changed<0;i--)for(int d=s[i]-'0'+1;d<10;d++)if(leftPrefix[i]+bits[d]+7*(n-i-1)>original){changed=i;result[i]='0'+d;break;}if(changed<0){cout<<-1<<'\n';return 0;}int maximum=leftPrefix[changed]+bits[result[changed]-'0'];for(int i=changed+1;i<n;i++)for(int d=0;d<10;d++)if(maximum+bits[d]+7*(n-i-1)>original){result[i]='0'+d;maximum+=bits[d];break;}for(int i=n-1;i>=0;i--)maxSuffix[i]=maxSuffix[i+1]+bits[result[i]-'0'];int sum=0;for(int i=0;i<n;i++)for(int d=0;d<10;d++)if(sum+score[result[i]-'0'][d]+maxSuffix[i+1]>original){result[n+i]='0'+d;sum+=score[result[i]-'0'][d];break;}cout<<result<<'\n';}
